import org.eclipse.jface.dialogs.MessageDialog;
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Shell;

class EditorMessages {
    public static String Editor_error_replace_button_label = "Replace";
    public static String Editor_error_dontreplace_button_label = "Do not replace";
    public static String Editor_error_activated_outofsync_title = "File Changed";
    public static String Editor_error_activated_outofsync_message = "The file '{0}' has been changed.";
}

public class Example {
    public boolean checkFile(Shell shell, String inputName) {
        String title = EditorMessages.Editor_error_activated_outofsync_title;
        String msg = EditorMessages.Editor_error_activated_outofsync_message;

        if (MessageDialog.openQuestion(shell, title, msg)) {
            System.out.println("User chose Yes.");
            return true;
        } else {
            System.out.println("User chose No.");
            return false;
        }
    }
}

